class Poll:
    def __init__(self, question: str) -> None:
        self.question = question
        self._options = []
        self._votes = {}
        self._voters = set()

    def add_option(self, option: str) -> None:
        if option not in self._options:
            self._options.append(option)

    def vote(self, voter: str, option: str) -> None:
        if voter in self._voters:
            raise ValueError(f"Voter {voter!r} has already voted")
        if option not in self._options:
            raise ValueError(f"Unknown option {option!r}")
        self._voters.add(voter)
        self._votes[option] = self._votes.get(option, 0) + 1

    def winner(self) -> str | None:
        if len(self._voters) < 3:
            return None
        best = None
        best_count = -1
        # Iterate in insertion order; later options win ties because
        # we use strict greater-than comparison.
        for option in self._options:
            count = self._votes.get(option, 0)
            if count > best_count:
                best_count = count
                best = option
        return best
